mapper.select:
SELECT id, imageHash, modelVersion, weightSha256, preprocessVersion, inferencePolicyVersion, predictedLabel, probability,
       calibratedProbability, calibrationStatus, description, reliabilityScore, topPredictions, qualityScore,
       qualityReasons, isOod, oodScore, oodStatus, rejected, abstainReason, requiresReview, createTime
FROM t_inference_cache
WHERE imageHash = #{imageHash}
  AND modelVersion = #{modelVersion}
  AND weightSha256 = #{weightSha256}
  AND preprocessVersion = #{preprocessVersion}
  AND inferencePolicyVersion = #{inferencePolicyVersion}
LIMIT 1
